"BOSS_SLAIN_1_DUELIST","BOSS_SLAIN_1_CLERIC","BOSS_SLAIN_1_ALL_CLASSES","RESEARCHER_2","GAMES_PLAYED_2","HIGH_SCORE_2","ENEMY_HAZARDS","PIRANHAS","GRIM_WEAPON","BAG_BOUGHT_VELVET_POUCH","BAG_BOUGHT_SCROLL_HOLDER","BAG_BOUGHT_POTION_BANDOLIER","BAG_BOUGHT_MAGICAL_HOLSTER","ALL_BAGS_BOUGHT","MASTERY_COMBO","MONSTERS_SLAIN_5","GOLD_COLLECTED_5","ITEM_LEVEL_4","LEVEL_REACHED_4","STRENGTH_ATTAINED_4","STRENGTH_ATTAINED_5","FOOD_EATEN_4","FOOD_EATEN_5","ITEMS_CRAFTED_4","ITEMS_CRAFTED_5","BOSS_SLAIN_4","ALL_RARE_ENEMIES",
"DEATH_FROM_GRIM_TRAP","VICTORY","BOSS_CHALLENGE_1","BOSS_CHALLENGE_2","RESEARCHER_3","GAMES_PLAYED_3","HIGH_SCORE_3","MANY_BUFFS","ITEM_LEVEL_5","LEVEL_REACHED_5","HAPPY_END","VICTORY_RANDOM","HAPPY_END_REMAINS","RODNEY","VICTORY_WARRIOR","VICTORY_MAGE","VICTORY_ROGUE","VICTORY_HUNTRESS","VICTORY_DUELIST","VICTORY_CLERIC","VICTORY_ALL_CLASSES","DEATH_FROM_ALL","BOSS_SLAIN_3_GLADIATOR","BOSS_SLAIN_3_BERSERKER","BOSS_SLAIN_3_WARLOCK","BOSS_SLAIN_3_BATTLEMAGE","BOSS_SLAIN_3_FREERUNNER","BOSS_SLAIN_3_ASSASSIN",
